class AutoCarnivalManager private constructor() {
    companion object {
        private const val CLICK_COOLDOWN_MS=200L; private const val AIM_TIMEOUT_MS=3000L; private const val DEBUG_THROTTLE_MS=1000L; private const val SCAN_DEBUG_THROTTLE_MS=2000L
        private const val SHOOTOUT_EXIT_CONFIRM_MS=1000L; private const val REPLAY_RETRY_COOLDOWN_MS=2000L; private const val REPLAY_START_GRACE_MS=6000L; private const val REPLAY_CHAT_CLICK_WINDOW_MS=15000L; private const val REPLAY_CLICK_DELAY_MS=1000L; private const val NPC_INTERACTION_TIMEOUT_MS=10000L
        private const val MAX_TARGET_DISTANCE_SQR=1600.0; private const val AIM_TOLERANCE_DEGREES=4.0f; private const val NPC_INTERACTION_RANGE=3.25f; private const val NPC_RETRY_RANGE=4.25f; private const val MAX_NPC_INTERACTION_RETRIES=2; private const val MAX_REPLAY_CLICK_ATTEMPTS=3
        private const val CARNIVAL_COWBOY_NAME="Carnival Cowboy"; private const val COWBOY_CONFIRM_TEXT="Sure thing"; private const val COWBOY_OPTION_PROMPT_TEXT="Select an option:"
        private val TOKEN_EARNED_PATTERN=Pattern.compile("You earned ([\\d,]+) Carnival Tokens?!",Pattern.CASE_INSENSITIVE)
        private val TICKET_EXHAUSTED_PATTERN=Pattern.compile(".*Carnival Cowboy.*Sorry pal, but ya need .*Carnival Tickets to play!.*",Pattern.CASE_INSENSITIVE)
        private val LAMP_COORDS=List.of(BlockPos(-119,75,45),BlockPos(-119,77,42),BlockPos(-118,76,39),BlockPos(-118,76,49),BlockPos(-117,76,52),BlockPos(-115,77,55),BlockPos(-112,76,58),BlockPos(-109,75,60),BlockPos(-106,77,61),BlockPos(-102,75,62),BlockPos(-99,77,62),BlockPos(-96,76,61))
        private var lastClickMs=0L; private var aimStartedMs=0L; private var lastDebugMs=0L; private var lastScanDebugMs=0L; private var lastDartSeenMs=0L; private var lastReplayAttemptMs=0L; private var waitingForNextShootoutUntilMs=0L
        private var pendingTarget:Vec3?=null; private var lastDebugMessage=""; private var sessionTokensEarned=0L; private var enabled=false; private var suppressAutoEnterUntilNoDart=false
        @Volatile private var shootoutSeen=false; @Volatile private var replayTaskQueued=false; @Volatile private var replayTaskRunning=false; @Volatile private var replayPromptClicked=false; @Volatile private var ticketExhausted=false; @Volatile private var retrySneakLatched=false; @Volatile private var replayTaskToken=0L; @Volatile private var pendingReplayClickEventAt=0L; @Volatile private var pendingReplayClickReadyAt=0L; @Volatile private var pendingReplayClickAttempts=0; @Volatile private var pendingReplayClickEvent:ClickEvent?=null
        @JvmStatic fun syncFromConfig(client:Minecraft){enabled=AetherConfig.AUTO_CARNIVAL_SHOOTOUT.get();if(!enabled)exitCarnivalState(client,true)}
        @JvmStatic fun setEnabled(client:Minecraft,enabled:Boolean){AetherConfig.AUTO_CARNIVAL_SHOOTOUT.set(enabled);AetherConfig.save();this.enabled=enabled;if(!enabled){exitCarnivalState(client,true);return};resetSession()}
        @JvmStatic fun stopForMacro(client:Minecraft){if(MacroStateManager.getCurrentState()==MacroState.State.AUTO_CARNIVAL)suppressAutoEnterUntilNoDart=true;stopActiveInteraction(client);resetSession()}
        @JvmStatic fun update(){val client=Minecraft.getInstance();if(!enabled)return;val player=client.player?:run{resetSession();return};val world=client.level?:run{resetSession();return};var state=MacroStateManager.getCurrentState();if(state!=MacroState.State.OFF&&state!=MacroState.State.AUTO_CARNIVAL){resetSession();return};if(client.gui.screen()!=null){resetAimState();return};val now=System.currentTimeMillis();val holdingDart=isHoldingDart(player.mainHandItem);if(!holdingDart)suppressAutoEnterUntilNoDart=false;if(state==MacroState.State.OFF){if(!holdingDart||suppressAutoEnterUntilNoDart)return;MacroStateManager.setCurrentState(MacroState.State.AUTO_CARNIVAL);state=MacroStateManager.getCurrentState();if(state!=MacroState.State.AUTO_CARNIVAL)return};if(holdingDart){shootoutSeen=true;replayPromptClicked=false;clearPendingReplayPrompt();waitingForNextShootoutUntilMs=0L;lastDartSeenMs=now;if(pendingTarget!=null){continuePendingShot(client,player,now);return};if(RotationManager.isRotating()||now-lastClickMs<CLICK_COOLDOWN_MS)return;val targets=gatherTargets(client,world,player);if(targets.isEmpty())return;val target=targets[0];pendingTarget=target;aimStartedMs=now;RotationManager.initiateRotation(client,target,0L);return};resetAimState();if(isReplayConfirmationPending())tryConsumePendingReplayPrompt(client);if(waitingForNextShootoutUntilMs>now)return;if(!shootoutSeen||ticketExhausted||replayTaskQueued||replayTaskRunning||isReplayConfirmationPending())return;if(now-lastDartSeenMs<SHOOTOUT_EXIT_CONFIRM_MS||now-lastReplayAttemptMs<REPLAY_RETRY_COOLDOWN_MS)return;queueReplayTask(client)}
        @JvmStatic fun handleChatMessage(client:Minecraft?,message:Component?,plainText:String?){if(!enabled||MacroStateManager.getCurrentState()!=MacroState.State.AUTO_CARNIVAL||client==null||message==null||plainText==null)return;trackTokenEarned(plainText);if(TICKET_EXHAUSTED_PATTERN.matcher(plainText).matches()){ticketExhausted=true;shootoutSeen=false;replayPromptClicked=false;clearPendingReplayPrompt();waitingForNextShootoutUntilMs=0L;ClientUtils.sendMessage("\u00A7eAuto Carnival ran out of Carnival Tickets. Stopping replay loop.",true);ClientUtils.sendDebugMessage("AutoCarnival: ticket gate detected, replay loop aborted.");exitCarnivalState(client,true);return};if(!shouldHandleReplayPrompt())return;val option=plainText.contains(COWBOY_OPTION_PROMPT_TEXT);if(!option&&!plainText.contains(COWBOY_CONFIRM_TEXT))return;val event=extractReplayClickEvent(message,option);if(event==null){ClientUtils.sendDebugMessage("AutoCarnival: confirmation message had no clickable event.");return};val now=System.currentTimeMillis();pendingReplayClickEvent=event;pendingReplayClickEventAt=now;pendingReplayClickReadyAt=now+REPLAY_CLICK_DELAY_MS;pendingReplayClickAttempts=0;ClientUtils.sendDebugMessage("AutoCarnival: cached Carnival Cowboy prompt click and waiting 1s before retrying.")}
        private fun queueReplayTask(client:Minecraft){replayTaskQueued=true;val token=++replayTaskToken;MacroWorkerThread.getInstance().submit("AutoCarnival-Replay"){runReplayTask(client,token)}}
        private fun runReplayTask(client:Minecraft,token:Long){replayTaskQueued=false;replayTaskRunning=true;lastReplayAttemptMs=System.currentTimeMillis();replayPromptClicked=false;if(pendingReplayClickEventAt<lastReplayAttemptMs)clearPendingReplayPrompt();try{if(!isReplayTaskCurrent(token)||client.player==null||client.level==null)return;var cowboy=findCowboyEntity(client)?:run{ClientUtils.sendDebugMessage("AutoCarnival: Carnival Cowboy not found after shootout.");return};cowboy=prepareCowboyForInteractionWithRetries(client,cowboy,token)?:run{ClientUtils.sendDebugMessage("AutoCarnival: failed to prep Carnival Cowboy interaction.");return};if(!isReplayTaskCurrent(token))return;if(!interactUntilReplayQueued(client,cowboy,token,NPC_INTERACTION_TIMEOUT_MS))ClientUtils.sendDebugMessage("AutoCarnival: no replay confirmation received from Carnival Cowboy.")}finally{replayTaskRunning=false;replayTaskQueued=false;retrySneakLatched=false}}
        private fun interactUntilReplayQueued(client:Minecraft,initial:Entity,token:Long,timeout:Long):Boolean{val deadline=System.currentTimeMillis()+timeout;var entity=initial;var retries=0;while(System.currentTimeMillis()<deadline&&isReplayTaskCurrent(token)){if(isBackInShootout(client)){onReplayRoundResumed(client);return true};if(tryConsumePendingReplayPrompt(client))return true;if(hasPendingReplayPrompt()){MacroWorkerThread.sleep(100L);continue};entity=findCowboyEntity(client)?:entity;val range=getRetryRangeForAttempt(retries);if(!isEntityInRetryRange(client,entity,range)||!isLookingAt(client,entity,AetherConfig.VISITOR_FOV_RANGE.get())){if(retries>=MAX_NPC_INTERACTION_RETRIES){ClientUtils.sendDebugMessage("AutoCarnival: interaction retries exceeded for Carnival Cowboy.");return false};retries++;ClientUtils.sendDebugMessage("AutoCarnival: re-prepping Carnival Cowboy interaction ($retries/$MAX_NPC_INTERACTION_RETRIES).");entity=prepareCowboyForInteraction(client,entity,getRetryRangeForAttempt(retries),token)?:continue};interactWithEntity(client,entity);for(i in 0 until 5){MacroWorkerThread.sleep(100L);if(isBackInShootout(client)){onReplayRoundResumed(client);return true};if(tryConsumePendingReplayPrompt(client))return true;if(!isReplayTaskCurrent(token))return false;if(ticketExhausted)return true}};return ticketExhausted||isBackInShootout(client)}
        private fun prepareCowboyForInteractionWithRetries(client:Minecraft,initial:Entity,token:Long):Entity?{var cowboy=initial;retrySneakLatched=false;for(attempt in 0..MAX_NPC_INTERACTION_RETRIES){if(!isReplayTaskCurrent(token))break;if(attempt>0)retrySneakLatched=true;val found=findCowboyEntity(client);if(found!=null)cowboy=found;val prepared=prepareCowboyForInteraction(client,cowboy,getRetryRangeForAttempt(attempt),token);if(prepared!=null)return prepared;if(attempt<MAX_NPC_INTERACTION_RETRIES){ClientUtils.sendDebugMessage("AutoCarnival: initial prep retry (${attempt+1}/$MAX_NPC_INTERACTION_RETRIES) for Carnival Cowboy.");MacroWorkerThread.sleep(250L)}};return null}
        private fun prepareCowboyForInteraction(client:Minecraft,initial:Entity,retryRange:Float,token:Long):Entity?{if(!isReplayTaskCurrent(token)||client.player==null)return null;var cowboy=findCowboyEntity(client)?:initial;if(!isEntityInRetryRange(client,cowboy,retryRange)){walkToEntity(client,cowboy,retryRange,token);if(!isReplayTaskCurrent(token))return null;cowboy=findCowboyEntity(client)?:cowboy};if(!isEntityInInteractionRange(client,cowboy))return null;faceEntityForInteraction(client,cowboy);return cowboy}
        private fun walkToEntity(client:Minecraft,entity:Entity,retryRange:Float,token:Long){if(client.player==null)return;var target=findBestWalkingTarget(client,entity,retryRange);if(target==null)target=entity.blockPosition();val x=target.x;val y=target.y;val z=target.z;ClientUtils.sendDebugMessage("AutoCarnival: walking to Carnival Cowboy at $x, $y, $z");try{val latch=retrySneakLatched;client.execute{PathfindingManager.startPathfind(client,x,y,z,false,entity);PathfindingManager.setWalkSneakLatched(latch)}}catch(_:Exception){};MacroWorkerThread.sleep(500L);val deadline=System.currentTimeMillis()+15000L;while(PathfindingManager.isNavigating()&&System.currentTimeMillis()<deadline&&isReplayTaskCurrent(token))MacroWorkerThread.sleep(200L);if(PathfindingManager.isNavigating())PathfindingManager.stop(false);try{client.execute{PathfindingManager.setWalkSneakLatched(false)}}catch(_:Exception){};MacroWorkerThread.sleep(200L)}
        private fun findBestWalkingTarget(client:Minecraft,entity:Entity,retryRange:Float):BlockPos?{val level=client.level?:return null;val player=client.player?:return null;val base=entity.blockPosition();var best:BlockPos?=null;var bestDist=Double.MAX_VALUE;val rangeSqr=retryRange*retryRange;for(x in -3..3)for(z in -3..3)for(y in -2..2){val pos=base.offset(x,y,z);if(pos.distToCenterSqr(entity.position())>rangeSqr)continue;if(!level.getBlockState(pos.below()).getCollisionShape(level,pos.below()).isEmpty&&level.getBlockState(pos).getCollisionShape(level,pos).isEmpty&&level.getBlockState(pos.above()).getCollisionShape(level,pos.above()).isEmpty){val d=pos.distToCenterSqr(player.position());if(d<bestDist){bestDist=d;best=pos}}};return best}
        private fun isWalkable(client:Minecraft,pos:BlockPos):Boolean{
            val level=client.level?:return false
            return !level.getBlockState(pos.below()).getCollisionShape(level,pos.below()).isEmpty&&level.getBlockState(pos).getCollisionShape(level,pos).isEmpty&&level.getBlockState(pos.above()).getCollisionShape(level,pos.above()).isEmpty
        }
        private fun isLookingAt(client:Minecraft,entity:Entity,tolerance:Float):Boolean{val p=client.player?:return false;return RotationUtils.isLookingAt(p.yRot,p.xRot,p.eyePosition,entity.eyePosition,tolerance)}
        private fun faceEntityForInteraction(client:Minecraft,entity:Entity){rotateToEntity(client,entity);waitForRotationToFinish();if(!isLookingAt(client,entity,AetherConfig.VISITOR_FOV_RANGE.get())){rotateToEntity(client,entity);waitForRotationToFinish()}}
        private fun rotateToEntity(client:Minecraft,entity:Entity){client.execute{RotationManager.initiateRotation(client,Vec3(entity.x,entity.eyeY,entity.z),AetherConfig.ROTATION_TIME.get().toLong(),AetherConfig.VISITOR_FOV_RANGE.get())};MacroWorkerThread.sleep(AetherConfig.ROTATION_TIME.get().toLong()+50L)}
        private fun waitForRotationToFinish(){val deadline=System.currentTimeMillis()+1500L;while(RotationManager.isRotating()&&System.currentTimeMillis()<deadline)MacroWorkerThread.sleep(25L)}
        private fun interactWithEntity(client:Minecraft,entity:Entity):Boolean{if(client.player==null||client.options==null)return false;client.execute{if(client.player!=null)(client as MixinMinecraft).`aether$startAttack`()};MacroWorkerThread.sleep(100L);return true}
        private fun findCowboyEntity(client:Minecraft):Entity?=EntityUtils.findEntity(client,CARNIVAL_COWBOY_NAME)
        private fun isEntityInInteractionRange(client:Minecraft,entity:Entity):Boolean=client.player?.distanceTo(entity)?.let{it<=NPC_INTERACTION_RANGE}?:false
        private fun isEntityInRetryRange(client:Minecraft,entity:Entity,range:Float):Boolean=client.player?.distanceTo(entity)?.let{it<=range}?:false
        private fun getRetryRangeForAttempt(attempt:Int):Float=Math.max(0.0f,NPC_RETRY_RANGE-attempt)
        private fun isReplayTaskCurrent(token:Long):Boolean=enabled&&MacroStateManager.getCurrentState()==MacroState.State.AUTO_CARNIVAL&&!ticketExhausted&&replayTaskToken==token
        private fun shouldHandleReplayPrompt():Boolean{if(ticketExhausted)return false;val now=System.currentTimeMillis();return replayTaskQueued||replayTaskRunning||(shootoutSeen&&now-lastReplayAttemptMs<=REPLAY_CHAT_CLICK_WINDOW_MS)}
        private fun tryConsumePendingReplayPrompt(client:Minecraft):Boolean{val event=pendingReplayClickEvent?:return false;if(!shouldHandleReplayPrompt())return false;if(isBackInShootout(client)){onReplayRoundResumed(client);return true};if(System.currentTimeMillis()-pendingReplayClickEventAt>REPLAY_CHAT_CLICK_WINDOW_MS){clearPendingReplayPrompt();return false};val now=System.currentTimeMillis();if(now<pendingReplayClickReadyAt)return false;if(pendingReplayClickAttempts>=MAX_REPLAY_CLICK_ATTEMPTS){ClientUtils.sendDebugMessage("AutoCarnival: replay prompt click retries exhausted.");clearPendingReplayPrompt();return false};if(client.player==null||client.connection==null)return false;val attempt=pendingReplayClickAttempts+1;pendingReplayClickAttempts=attempt;pendingReplayClickReadyAt=now+REPLAY_CLICK_DELAY_MS;client.execute{if(client.player!=null&&client.connection!=null){val screen=client.gui.screen();if(screen!=null)(screen as AccessorScreen).`aether$defaultHandleGameClickEvent`(event,client,screen)}};ClientUtils.sendDebugMessage("AutoCarnival: clicked cached Carnival Cowboy confirmation ($attempt/$MAX_REPLAY_CLICK_ATTEMPTS).");return false}
        private fun continuePendingShot(client:Minecraft,player:LocalPlayer,now:Long){val target=pendingTarget?:return;if(now-aimStartedMs>AIM_TIMEOUT_MS){resetAimState();return};if(RotationUtils.isLookingAt(player.yRot,player.xRot,player.eyePosition,target,AIM_TOLERANCE_DEGREES)){ClientUtils.performUseClick();lastClickMs=now;resetAimState();return};aimStartedMs=now;RotationManager.initiateRotation(client,target,0L)}
        private fun gatherTargets(client:Minecraft,world:ClientLevel,player:LocalPlayer):java.util.List<Vec3>{val diamond=ArrayList<Vec3>();val gold=ArrayList<Vec3>();val iron=ArrayList<Vec3>();val leather=ArrayList<Vec3>();val names=ArrayList<String>();var zombies=0;var nearby=0;var named=0;for(entity in world.entitiesForRendering()){if(entity !is Zombie)continue;zombies++;if(entity.distanceToSqr(player)>MAX_TARGET_DISTANCE_SQR)continue;nearby++;val chest=entity.getItemBySlot(EquipmentSlot.CHEST);if(chest.isEmpty)continue;named++;val aim=projectAhead(entity,player);val name=chest.hoverName.string.lowercase(Locale.ROOT);if(names.size<6)names.add(name);when{name.contains("diamond")->diamond.add(aim);name.contains("gold")->gold.add(aim);name.contains("iron")->iron.add(aim);name.contains("leather")->leather.add(aim)}};val lamps=ArrayList<Vec3>();var lit=0;for(pos in LAMP_COORDS){val state=world.getBlockState(pos);if(isActiveLamp(world,pos,state)){lit++;lamps.add(Vec3(pos.x+0.5,pos.y+0.6,pos.z+0.5))}};debugScan(client,zombies,nearby,named,diamond.size,gold.size,iron.size,leather.size,lit,names.toList() as java.util.List<String>);val targets=ArrayList<Vec3>(diamond.size+lamps.size+gold.size+iron.size+leather.size);targets.addAll(diamond);targets.addAll(lamps);targets.addAll(gold);targets.addAll(iron);targets.addAll(leather);return targets.toList() as java.util.List<Vec3>}
        private fun isActiveLamp(world:ClientLevel,pos:BlockPos,state:BlockState):Boolean{if(!state.`is`(Blocks.REDSTONE_LAMP))return false;if(state.hasProperty(BlockStateProperties.LIT)&&state.getValue(BlockStateProperties.LIT))return true;return state.lightEmission>0}
        private fun projectAhead(target:Zombie,player:LocalPlayer):Vec3{val distance=Math.sqrt(target.distanceToSqr(player));val base=Mth.clamp(distance/6.0,1.0,12.0);val ping=Math.max(AetherConfig.AUTO_CARNIVAL_PING.get(),0)/50.0;val lead=base+ping;val velocity=target.deltaMovement;return Vec3(target.x+velocity.x*lead,target.eyeY,target.z+velocity.z*lead)}
        private fun isHoldingDart(item:ItemStack):Boolean=!item.isEmpty&&item.hoverName.string.lowercase(Locale.ROOT).contains("dart")
        private fun resetAimState(){aimStartedMs=0L;pendingTarget=null}
        private fun resetSession(){lastClickMs=0L;lastDartSeenMs=0L;lastReplayAttemptMs=0L;resetAimState();shootoutSeen=false;replayTaskQueued=false;replayTaskRunning=false;replayPromptClicked=false;ticketExhausted=false;retrySneakLatched=false;waitingForNextShootoutUntilMs=0L;clearPendingReplayPrompt();replayTaskToken++}
        private fun isReplayConfirmationPending():Boolean=pendingReplayClickEvent!=null||pendingReplayClickAttempts>0
        private fun hasPendingReplayPrompt():Boolean=pendingReplayClickEvent!=null
        private fun isBackInShootout(client:Minecraft):Boolean=client.player?.let{isHoldingDart(it.mainHandItem)}?:false
        private fun onReplayRoundResumed(client:Minecraft){replayPromptClicked=true;clearPendingReplayPrompt();waitingForNextShootoutUntilMs=System.currentTimeMillis()+REPLAY_START_GRACE_MS;ClientUtils.sendDebugMessage("AutoCarnival: replay round resumed.")}
        private fun clearPendingReplayPrompt(){pendingReplayClickEvent=null;pendingReplayClickEventAt=0L;pendingReplayClickReadyAt=0L;pendingReplayClickAttempts=0}
        @JvmStatic fun resetTokenSession(){sessionTokensEarned=0L}
        @JvmStatic fun getSessionTokensEarned():Long=sessionTokensEarned
        @JvmStatic fun getSessionTokensPerHour():Long{val session=MacroStateManager.getSessionRunningTime();if(session<=0L)return 0L;return Math.round(sessionTokensEarned*(3_600_000.0/session))}
        private fun exitCarnivalState(client:Minecraft,update:Boolean){suppressAutoEnterUntilNoDart=true;stopActiveInteraction(client);resetSession();if(update&&MacroStateManager.getCurrentState()==MacroState.State.AUTO_CARNIVAL)MacroStateManager.setCurrentState(MacroState.State.OFF)}
        private fun stopActiveInteraction(client:Minecraft?){RotationManager.cancelRotation();if(PathfindingManager.isNavigating())PathfindingManager.stop(false);val active=client?:Minecraft.getInstance()?:return;try{active.execute{PathfindingManager.setWalkSneakLatched(false)}}catch(_:Exception){}}
        private fun debug(client:Minecraft?,message:String){if(client==null)return;val now=System.currentTimeMillis();if(message==lastDebugMessage&&now-lastDebugMs<DEBUG_THROTTLE_MS)return;lastDebugMessage=message;lastDebugMs=now;ClientUtils.sendDebugMessage(message)}
        private fun trackTokenEarned(text:String){val matcher=TOKEN_EARNED_PATTERN.matcher(text);if(!matcher.find())return;try{sessionTokensEarned+=java.lang.Long.parseLong(matcher.group(1).replace(",",""))}catch(_:NumberFormatException){}}
        private fun debugScan(client:Minecraft?,zombies:Int,nearby:Int,named:Int,diamond:Int,gold:Int,iron:Int,leather:Int,lamps:Int,names:List<String>){if(client==null)return;val now=System.currentTimeMillis();if(now-lastScanDebugMs<SCAN_DEBUG_THROTTLE_MS)return;lastScanDebugMs=now;val message=StringBuilder("Auto Carnival scan: zombies=").append(zombies).append(", nearby=").append(nearby).append(", chest=").append(named).append(", d=").append(diamond).append(", g=").append(gold).append(", i=").append(iron).append(", l=").append(leather).append(", lamps=").append(lamps);if(names.isNotEmpty())message.append(", names=").append(names);debug(client,message.toString())}
        private fun extractReplayClickEvent(component:Component,preferFirst:Boolean):ClickEvent?{if(preferFirst){val first=findFirstAllowedClickEvent(component);if(isAllowedServerClickEvent(first))return first};val targeted=findClickEvent(component,COWBOY_CONFIRM_TEXT);if(isAllowedServerClickEvent(targeted))return targeted;val first=findFirstAllowedClickEvent(component);return if(isAllowedServerClickEvent(first))first else null}
        private fun findClickEvent(component:Component?,target:String):ClickEvent?{if(component==null)return null;for(flat in component.toFlatList()){val event=flat.style.clickEvent;if(event!=null&&flat.string.contains(target))return event};if(component.string.contains(target))return findAnyClickEvent(component);return null}
        private fun findFirstAllowedClickEvent(component:Component?):ClickEvent?{if(component==null)return null;for(flat in component.toFlatList()){val event=flat.style.clickEvent;if(isAllowedServerClickEvent(event))return event};return findAnyClickEvent(component)}
        private fun findAnyClickEvent(component:Component?):ClickEvent?{if(component==null)return null;val event=component.style.clickEvent;if(event!=null)return event;for(sibling in component.siblings){val nested=findAnyClickEvent(sibling);if(nested!=null)return nested};return null}
        private fun isAllowedServerClickEvent(event:ClickEvent?):Boolean=event!=null&&event.action().isAllowedFromServer()
    }
}
